    /** @return array<int|string, string> */
    public static function options(?Region $region = null, ?Province $province = null): array
    {
        $options = [];

        foreach (self::cases() as $case) {
            if (($region !== null && $case->region() !== $region) || ($province !== null && $case->province() !== $province)) {
                continue;
            }

            $options[$case->value] = $case->label();
        }

        return $options;
    }
